package com.payroll.service; import com.payroll.model.*; import com.payroll.repository.*; import org.springframework.stereotype.Service; import java.time.*; import java.util.*; @Service public class PayrollService { private final PayrollRepository repo; private final EmployeeService employees; private final AuditService audit; public PayrollService(PayrollRepository r,EmployeeService e,AuditService a){repo=r;employees=e;audit=a;} public List<Payroll> all(){return repo.findAll();} public Payroll get(Long id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Payroll not found"));} public Payroll generate(Long emp,int month,int year,String user){if(month<1||month>12)throw new IllegalArgumentException("Month must be between 1 and 12");if(year<2000||year>2100)throw new IllegalArgumentException("Invalid year");if(repo.findByEmployeeIdAndMonthAndYear(emp,month,year).isPresent())throw new IllegalArgumentException("Payroll already exists for this period");Payroll p=new Payroll();p.setEmployee(employees.get(emp));p.setMonth(month);p.setYear(year);p.setGeneratedAt(LocalDateTime.now());PayrollCalculator.calculate(p);Payroll saved=repo.save(p);audit.record(user,"GENERATE","Payroll",saved.getId().toString(),"Generated payroll for "+p.getEmployee().getFullName());return saved;} }